import React, { useEffect, useMemo, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { connect } from 'react-redux'
import { NotificationContainer, NotificationManager } from 'react-notifications'
import { get, size } from 'lodash'
import { CustomText } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import customerActions from '../../../../../../redux/customer/actions'
import { Hr, Row } from '../../../../../../commonStyle/index.style'
import VTitleValue from '../../../CustomerPolicy/components/VTitlevalue'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { PROPERTY_LANG } from '../../../../../Private/Property/lang'
import {
  getBuildingDataSummary, getCustomerData, getPolicyDetail, PROPERTY_CUSTOMER_NOTE
} from '../../constants'
import { CustomerNoteStyle} from '../../../CustomerPolicy/index.style'
import { DOWNLOAD, BUY_PROPERTY_HOME } from '../../../../../../images'
import policyActions from '../../../../../../redux/policy/action'
import { downloadFile } from '../../../../../../methods/file'
import WarningModal from '../../../../../../components/WarningModal'
import PolicyInfo from '../../../../../../components/PolicyCancelledRejectionInfo'
import { MANUAL_ORDER } from '../../../../../../constants/pkgCode'
import PropertyPremiumSummary from './components/PropertyPremiumDetail'
import ProviderInfoCard from './components/ProviderInfoCard'
import { PropertyLandingBtn, PropertyLandingStyle } from './index.style'
import ZoomImg from '../../../../../../components/zoomImg'
import SingleImgContainer from '../../../../../../components/SingleImgContainer'
import { formatDate } from '../../../../../../helpers/formatDate'

const { getCustomerPolicy, resetCustomerStore } = customerActions
const { resetPolicyStore, getDraftDownloadPdfReq } = policyActions

function PropertyLanding (props) {
  const {
    policyDraftPdfStatus,
    customerPolicy = {}, policyDraftPdfData,
    resetPolicyStore, pdfFileDownloadError, getDraftDownloadPdfReq
  } = props
  const history = useHistory()
  const { draftQuoteId } = useParams()
  const {
    customer_data: customerData = {},
    product = {},
    status,
    policy_detail: policyDetail
  } = customerPolicy

  const isManualOrder = useMemo(() => customerPolicy?.policy_detail?.protection_case === MANUAL_ORDER, [customerPolicy])
  const [showModal, setShowModal] = useState(false)
  const hideBuyInsurance = ['VERIFICATION_PENDING', 'VERIFICATION_FAILED'].includes(status)
  const isApplicationCancelled = ['CANCELLED', 'REJECTED'].includes(customerPolicy?.policy_status)

  useEffect(() => {
    if (policyDraftPdfStatus === 'success' && policyDraftPdfData) {
      downloadFile(policyDraftPdfData.pdf_url)
      resetPolicyStore(['policyDraftPdfStatus'])
    } else if (policyDraftPdfStatus && pdfFileDownloadError) {
      NotificationManager.error(policyDraftPdfStatus)
      resetPolicyStore(['policyDraftPdfStatus'])
    }
  }, [policyDraftPdfStatus, policyDraftPdfData, pdfFileDownloadError, resetPolicyStore])

  const handleBtnClick = (btnType) => {
    // here on basis of click move the user to that page
    if (btnType === 'buyInsuranceBtn') {
      handleBuyInsuranceNow()
      return
    }
    getDraftDownloadPdfReq(draftQuoteId)
  }

  const handleToggleModal = () => {
    setShowModal(!showModal)
  }

  const handleBuyInsuranceNow = () => {
    history.push(`/customer/waiting/${draftQuoteId}/`)
  }

  const renderSectionTitle = (title) => {
    return (
      <CustomText
        size='16px'
        weight={800}
        color={AgentColorPallette.darkerGold}
      >
        {title}
      </CustomText>
    )
  }

  const renderCustomerData = () => {
    return (
      <>
        {renderSectionTitle(`2. ${LANG_STRINGS.policyHolderData}`)}
        {getCustomerData(customerData)?.map((item, i) => {
        return (
          <VTitleValue
            key={i}
            title={item.title}
            titleSize='12px'
            valueSize='13px'
            value={item.value}
            valueColor={AgentColorPallette.black}
            className={`property-provider ${item.className ? item.className : ''}`}
          />
        )
        })}
      </>
    )
  }

  const renderPolicyDate = () => {
    let startDate = formatDate(policyDetail?.start_date, 'DD/MM/YYYY [12:00 Siang]')
    let endDate = formatDate(policyDetail?.end_date, 'DD/MM/YYYY [12:00 Siang]')
    if (isManualOrder) {
      startDate = formatDate(customerPolicy?.policy_detail?.coverage_period_start, 'DD/MM/YYYY')
      endDate = formatDate(customerPolicy?.policy_detail?.coverage_period_end, 'DD/MM/YYYY')
    }
    const policyDetailData = getPolicyDetail({
      coveragePeriod: `${startDate} - ${endDate}`,
      packageType: customerPolicy?.package?.name
    })

    return (
      <>
        {renderSectionTitle(`1. ${LANG_STRINGS.policyDetail}`)}
        {policyDetailData.map((item, i) => {
          return (
            <VTitleValue
              key={i}
              title={item.title}
              titleSize='12px'
              valueSize='13px'
              value={item.value}
              valueColor={AgentColorPallette.black}
              className={`property-provider ${item.className ? item.className : ''}`}
            />
          )
        })}
      </>
    )
  }

  const renderBuildingData = () => {
    const buildingData = getBuildingDataSummary(customerPolicy, isManualOrder) || []
    return (
      <>
        {renderSectionTitle(`3. ${PROPERTY_LANG.buildingData}`)}
        {
          buildingData.map(item =>
            <VTitleValue
              key={item.title}
              title={item.title}
              titleSize='12px'
              valueSize='13px'
              value={item.value}
              valueColor={AgentColorPallette.black}
              className='property-provider'
            />
          )
        }
      </>
    )
  }

  const renderPremium = () => {
    return (
      <>
        {renderSectionTitle(`4. ${LANG_STRINGS.customerPremium}`)}
        <PropertyPremiumSummary policy={customerPolicy} isManualOrder={isManualOrder} />
      </>
    )
  }

  const renderNotes = (title, notes, padding) => {
    if (!size(notes)) return null
    return (
      <CustomerNoteStyle padding={padding}>
        <CustomText
          color={AgentColorPallette.black}
          bottom='4px'
          size='13px'
          weight={800}
        >
          {title}:
        </CustomText>
        {
          notes.map((note, index) => (
            <React.Fragment key={index}>
              <CustomText
                key={`note_${index}`}
                color={AgentColorPallette.black}
                bottom='4px'
                lineHeight={1.5}
              >
                {`${index + 1}. ${note.title || note}`}
              </CustomText>
              {
                note.description && (
                  Array.isArray(note.description) ? (
                    note.description.map((desc, descIndex) => (
                      <CustomText
                        key={`desc_${descIndex}`}
                        color={AgentColorPallette.black}
                        bottom='4px'
                        lineHeight={1.5}
                        size='10px'
                        className='note-description'
                      >
                        &bull;&nbsp;{desc}
                      </CustomText>
                    ))
                  ) : (
                    <>
                      <CustomText
                        color={AgentColorPallette.black}
                        bottom='4px'
                        lineHeight={1.5}
                        size='10px'
                      >
                        {note.description}
                      </CustomText>
                    </>
                  )
                )
              }
              {note.image_url && (
                <ZoomImg
                  src={note.image_url}
                  imgContainer={
                    <SingleImgContainer
                      minWidth='60px'
                      height='124px'
                      imgUrl={note.image_url}
                      imgClassName='single-img-margin'
                    />
                  }
                />
              )}
              {note.items?.map((item, itemIndex) => (
                <CustomText
                  key={`item_${itemIndex}`}
                  color={AgentColorPallette.black}
                  bottom='4px'
                  lineHeight={1.5}
                  size='10px'
                  className='note-description'
                >
                  &bull;&nbsp;{item}
                </CustomText>
              ))}
            </React.Fragment>
          ))
        }
      </CustomerNoteStyle>
    )
  }

  const renderBtnIcon = (title, icon, className, btnType) => {
    return (
      <Row align='center' justify='space-between' onClick={() => handleBtnClick(btnType)} className={className}>
        <CustomText
          weight={800}
          color={AgentColorPallette.black}
          size='14px'
          className='btn-text'
        >
          {title}
        </CustomText>
        <img src={icon} alt='' />
      </Row>
    )
  }

  return (
    <>
      <PropertyLandingStyle className='bg-white' isApplicationCancelled={isApplicationCancelled}>
        <PolicyInfo
          remarks={customerPolicy?.insurance_details?.remark_details || {}}
          status={customerPolicy?.policy_status || ''}
        />
        <ProviderInfoCard
          logo={product?.logo_url}
          providerName={product?.provider?.name}
          productName={product?.name}
          draftId={draftQuoteId}
        />
        <Hr />
        {renderPolicyDate()}
        <Hr />
        {renderCustomerData()}
        <Hr />
        {renderBuildingData()}
        <Hr />
        {renderPremium()}
        {renderNotes('Detail Manfaat', get(customerPolicy, 'product.benefit.data[0].benefit_list', []))}
        {renderNotes('Klausul Tambahan', get(customerPolicy, 'product.common_clause_content', []))}
        {renderNotes(PROPERTY_LANG.deductiblesOwnRisk, get(customerPolicy, 'product.common_deductible_content', []))}
        {renderNotes(LANG_STRINGS.note, PROPERTY_CUSTOMER_NOTE, '10px 0 30%')}
      </PropertyLandingStyle>
      {
        !isApplicationCancelled && (
          <PropertyLandingBtn>
            {
              renderBtnIcon(
                LANG_STRINGS.downloadOffer,
                DOWNLOAD,
                'download-offer-btn',
                'downloadOfferBtn'
              )
            }
            {
              !hideBuyInsurance && renderBtnIcon(
                LANG_STRINGS.buyInsuranceNow,
                BUY_PROPERTY_HOME,
                'property-btn',
                'buyInsuranceBtn'
              )
            }
          </PropertyLandingBtn>
        )
      }
      <WarningModal
        showModal={showModal}
        hideCloseBtn
        hideIcon
        warning={LANG_STRINGS.youCanNotPayThisCustomer}
        onClose={handleToggleModal}
        onOk={handleToggleModal}
      />
      <NotificationContainer />
    </>
  )
}

export default connect(
    state => ({
      policyDraftPdfStatus: state.Policy.policyDraftPdfStatus,
      policyDraftPdfData: state.Policy.policyDraftPdfData,
      pdfFileDownloadError: state.Error.GET_DOWNLOAD_PDF
    }),
    {
      getCustomerPolicy,
      getDraftDownloadPdfReq,
      resetCustomerStore,
      resetPolicyStore
    }
  )(PropertyLanding)
