import React from 'react'
import { PropertyTransactionDetailWrapper, SectionSeparator, TransactionTotalContainer } from './index.style'
import { CustomText } from '../../../../../../../../components'
import AmountTitle from '../../../../../../../../components/AmountTitle'
import { get } from 'lodash'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../../../../helpers/utility'


    const renderAddonItem = (item) => {
      if (!item.tsi_multiplied_limit_of_liability || item.tsi_multiplied_limit_of_liability === 0) {
        return null
      }

      return (
        <AmountTitle
          key={item.addon_code}
          title={item.addon_title}
          amount={item.premium}
          amountWeight={400}
          className='property-amount'
          size='10px'
          subtitle={
            <>
              (<span style={{ color: AgentColorPallette.earthGreen }}>
                {formatMoney(item.tsi_multiplied_limit_of_liability, 2)}
              </span> X {item.percentage}%)
            </>
          }
        />
      )
    }

const PropertyTransactionDetail = ({ data }) => {
  const basePremium = get(data, 'base_premium.premium', 0)
  const stampDuty = get(data, 'stamp_duty', 0)
  const adminFee = get(data, 'admin_fee', 0)
  const discount = get(data, 'discount', 0)
  const totalBill = get(data, 'total_bill', basePremium + stampDuty + adminFee - discount)

  
  return (
    <PropertyTransactionDetailWrapper>
      {data && data.addon_categorization && data?.addon_categorization.map((sectionItem, index) => {
        // calculate subtotal by summing premiums
        // the data is missing from backend so using reduce to sum it up
        // once backend is fixed, this can be replaced by sectionItem.subtotal or similar field
        const subtotal = sectionItem?.addon_list?.reduce((acc, item) => acc + (item.premium || 0), 0)

        return (
          <React.Fragment key={index}>
            <CustomText
              size='10px'
              weight={800}
              color='#000'
              bottom='8px'
            >
              {sectionItem.title}
            </CustomText>
            {sectionItem?.addon_list.map((item) => renderAddonItem(item))}
            <SectionSeparator />
            <AmountTitle
              title='Sub Total'
              amount={subtotal}
              amountWeight={800}
              titleWeight={800}
              className='property-amount'
              size='10px'
            />
          </React.Fragment>
        )
      })}

      <SectionSeparator color='#0078FA' />
      <AmountTitle
        color='#0078FA'
        amount={basePremium}
        title='Total Premi Dasar'
        amountWeight={800}
        titleWeight={800}
        className='property-amount'
        size='10px'
      />
      <CustomText
        color='#000'
        size='10px'
        weight={800}
        bottom='8px'
      >
        Lainnya
      </CustomText>
      <AmountTitle
        amount={stampDuty}
        title='Biaya Materai'
        className='property-amount'
        size='10px'
      />
      <AmountTitle
        amount={adminFee}
        title='Biaya Administrasi'
        className='property-amount'
        size='10px'
      />
      <AmountTitle
        amount={discount}
        title='Diskon'
        className='property-amount'
        size='10px'
        color='#FA3232'
        amountWeight={800}
        titleWeight={800}
      />
      <TransactionTotalContainer>
        <AmountTitle
          amount={totalBill}
          title='Total Transaksi'
          color='#FFF'
          size='12px'
          amountWeight={800}
          titleWeight={800}
        />
      </TransactionTotalContainer>
    </PropertyTransactionDetailWrapper>
  )
}

export default PropertyTransactionDetail
