import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useCustomerContextValue } from '../../context'
import {
  getCustomerApplicationDetail, getDownloadPdf, getFwdTncUrl,
  submitCustomerPolicy, updateCustomerApplication, getCustomerDraftDetailsReq,
  completeCustomerDraftQuoteReq, updateCustomerDraftQuoteReq
} from '../actions'

export const useCustomerServiceCall = (actionsCall = () => {}) => {
  const [policyState, dispatch] = useCustomerContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [policyState, request]
}

export const useGetCustomerApplicationDetail = () => useCustomerServiceCall(getCustomerApplicationDetail)
export const useGetDownloadPdf = () => useCustomerServiceCall(getDownloadPdf)
export const useUpdateCustomerApplication = () => useCustomerServiceCall(updateCustomerApplication)
export const useSubmitCustomerPolicy = () => useCustomerServiceCall(submitCustomerPolicy)
export const useGetFwdTncUrl = () => useCustomerServiceCall(getFwdTncUrl)
export const useGetCustomerDraftDetails = () => useCustomerServiceCall(getCustomerDraftDetailsReq)
export const useCompleteCustomerDraft = () => useCustomerServiceCall(completeCustomerDraftQuoteReq)
export const useUpdateCustomerDraft = () => useCustomerServiceCall(updateCustomerDraftQuoteReq)
