import { get } from 'lodash'
import { LANG_STRINGS } from '../../../../../lang'
import { PROPERTY_LANG } from '../../../../Private/Property/lang'

export const getCustomerData = (data) => {
  const customerTypeMap = {
    individual: PROPERTY_LANG.individualOwner,
    corporate: PROPERTY_LANG.corporateOwner
  }
  
  if (data.type === 'individual') {
    return [
      {
        title: LANG_STRINGS.ownership,
        value: customerTypeMap[data?.type]
      },
      {
        title: LANG_STRINGS.fullName,
        value: data?.name
      }
    ]
  }
  if (data.type === 'corporate') {
    return [
      {
        title: LANG_STRINGS.ownership,
        value: customerTypeMap[data?.type]
      },
      {
        title: PROPERTY_LANG.corporateName,
        value: data?.corporate_data?.name
      }
    ]
  }
}

const renderYesNoValue = (data) => {
  return data ? 'Iya' : 'Tidak'
}

export const getBuildingDataSummary = (data = {}, isManualOrder = false) => {
  const questionare = data.policy_detail.questionnaire.map(item => {
    return {
      title: item.question,
      value: renderYesNoValue(item.value)
    }
  })

  return [
    {
      title: PROPERTY_LANG.province,
      value: get(data, 'policy_detail.province_name', '')
    },
    {
      title: PROPERTY_LANG.city,
      value: get(data, 'policy_detail.city_name', '')
    },
    {
      title: LANG_STRINGS.postalCode,
      value: get(data, 'policy_detail.postal_code', '')
    },
    {
      title: PROPERTY_LANG.insuredObjectLocation,
      value: get(data, 'policy_detail.property_address', '')
    },
    {
      title: LANG_STRINGS.category,
      value: get(data, 'policy_detail.property_data.occupation_data.occupation_name_mitra', '')
    },
    {
      title: PROPERTY_LANG.buildingUse,
      value: get(data, 'policy_detail.property_data.occupation_data.occupation_desc_mitra', '')
    },
    {
      title: PROPERTY_LANG.noOfFloor,
      value: get(data, 'policy_detail.property_data.no_of_floor', '')
    },
    ...questionare
  ]
}

export const getPropertyPremium = (data = {}, isManualOrder = false) => {
  let propertyBreakup = get(data, 'product.premium_breakup.property_sum_insured_breakup', {})
  if (isManualOrder) {
    propertyBreakup = get(data, 'policy_detail', {})
  }
  return [
    {
      title: PROPERTY_LANG.buildingValue,
      value: get(propertyBreakup, 'building_value', 0)
    },
    {
      title: PROPERTY_LANG.valueOfBuildingContent,
      value: get(propertyBreakup, 'building_content_value', 0)
    },
    {
      title: PROPERTY_LANG.machineValue,
      value: get(propertyBreakup, 'machine_value', 0)
    },
    {
      title: PROPERTY_LANG.equipmentValue,
      value: get(propertyBreakup, 'equipment_value', 0)
    },
    {
      title: PROPERTY_LANG.stockValue,
      value: get(propertyBreakup, 'stock_value', 0)
    }

  ]
}

export const getPolicyDetail = (data) => {
  return [
    {
      title: LANG_STRINGS.coveragePeriod,
      value: get(data, 'coveragePeriod', '')
    },
    {
      title: LANG_STRINGS.packageTitle,
      value: get(data, 'packageType', '')
    }
  ]
}

