import moment from 'moment'

export function formatDate(date, format = 'DD/MM/YYYY') {
  if (!date) return undefined
  return moment(date).format(format)
}

export function isDateValid(date, format) {
  if (!date) return false
  return (format ? moment(date, format) : moment(date))?._isValid
}

export function isDateBefore(date1, date2, isSame = false) {
  if (isSame) return moment(date1).isSameOrBefore(date2)
  return moment(date1).isBefore(date2)
}

export function isDateAfter(date1, date2, isSame = false) {
  if (isSame) return moment(date1).isSameOrAfter(date2)
  return moment(date1).isAfter(date2)
}

/**
 * @param {Date|string} date
 * @param {number} num
 * @param {'day'|'days'|'month'|'months'|'year'|'years'} unit
 * @returns {moment.Moment}
 */
export function dateAdd(date, num, unit) {
  if (!date) return undefined
  return moment(date).add(num, unit)
}

/**
 * @param {Date|string} date
 * @param {number} num
 * @param {'day'|'days'|'month'|'months'|'year'|'years'} unit
 * @returns {moment.Moment}
 */
export function dateSubtract(date, num, unit) {
  if (!date) return undefined
  return moment(date).subtract(num, unit)
}

/**
 * Calculates calendar-aware difference between two datetimes.
 * @param {Date|string} target
 * @param {Date|string} reference
 * @returns {{years:number, months:number, days:number, hours:number, minutes:number, seconds:number}|undefined}
 */
export function getDateDifference(target, reference = new Date()) {
  if (!target) return undefined

  const targetMoment = moment(target)
  const referenceMoment = moment(reference)
  if (!targetMoment?._isValid || !referenceMoment?._isValid) return undefined

  // If target is in the past, treat as no remaining time.
  if (targetMoment.isSameOrBefore(referenceMoment)) {
    return { years: 0, months: 0, days: 0, hours: 0, minutes: 0, seconds: 0 }
  }

  const cursor = referenceMoment.clone()
  const years = targetMoment.diff(cursor, 'years')
  cursor.add(years, 'years')
  const months = targetMoment.diff(cursor, 'months')
  cursor.add(months, 'months')
  const days = targetMoment.diff(cursor, 'days')
  cursor.add(days, 'days')
  const hours = targetMoment.diff(cursor, 'hours')
  cursor.add(hours, 'hours')
  const minutes = targetMoment.diff(cursor, 'minutes')
  cursor.add(minutes, 'minutes')
  const seconds = targetMoment.diff(cursor, 'seconds')

  return { years, months, days, hours, minutes, seconds }
}

/**
 * Returns human-readable time between target and reference (calendar-aware).
 * When reference is before target: time until target ("… lagi").
 * When reference is after target: elapsed time since target ("… lewat").
 * When they are the same instant: "0 detik lagi".
 * @param {Date|string} target
 * @param {Date|string} reference
 * @param {('s'|'m'|'h'|'D'|'M'|'Y')[]} units
 * @returns {string|undefined}
 */
export function getRemainingDatetime(
  target,
  reference = new Date(),
  units = ['s', 'm', 'h', 'D', 'M', 'Y']
) {
  if (!target) return undefined

  const targetMoment = moment(target)
  const referenceMoment = moment(reference)
  if (!targetMoment?._isValid || !referenceMoment?._isValid) return undefined

  if (referenceMoment.isBefore(targetMoment)) {
    const diff = getDateDifference(target, reference)
    if (!diff) return undefined

    let { years, months, days, hours, minutes, seconds } = diff
    if (!units.includes('Y')) {
      months += years * 12
      years = 0
    }
    if (!units.includes('M')) {
      days += months * 30
      months = 0
    }
    if (!units.includes('D')) {
      hours += days * 24
      days = 0
    }
    if (!units.includes('h')) {
      minutes += hours * 60
      hours = 0
    }
    if (!units.includes('m')) {
      seconds += minutes * 60
      minutes = 0
    }

    if (years > 0) return `${years} tahun lagi`
    if (months > 0) return `${months} bulan lagi`
    if (days > 0) return `${days} hari lagi`
    if (hours > 0) return `${hours} jam lagi`
    if (minutes > 0) return `${minutes} menit lagi`
    return `${Math.max(0, seconds)} detik lagi`
  }

  if (referenceMoment.isAfter(targetMoment)) {
    const diff = getDateDifference(reference, target)
    if (!diff) return undefined

    let { years, months, days, hours, minutes, seconds } = diff
    if (!units.includes('Y')) {
      months += years * 12
      years = 0
    }
    if (!units.includes('M')) {
      days += months * 30
      months = 0
    }
    if (!units.includes('D')) {
      hours += days * 24
      days = 0
    }
    if (!units.includes('h')) {
      minutes += hours * 60
      hours = 0
    }
    if (!units.includes('m')) {
      seconds += minutes * 60
      minutes = 0
    }

    if (years > 0) return `+${years} tahun lewat`
    if (months > 0) return `+${months} bulan lewat`
    if (days > 0) return `+${days} hari lewat`
    if (hours > 0) return `+${hours} jam lewat`
    if (minutes > 0) return `+${minutes} menit lewat`
    return `+${Math.max(0, seconds)} detik lewat`
  }

  return '0 detik lagi'
}
