import {
  resetError,
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import get from 'lodash/get'
import { useCallback, useEffect, useState } from 'react'
import { withRouter } from 'react-router'
import { Row } from '../../../../../../../commonStyle/index.style'
import { Button, CustomText } from '../../../../../../../components'
import CircularLoader from '../../../../../../../components/CircularLoader'
import InsuranceInfoCard from '../../../../../../../components/InsuranceInfoCard'
import ProviderInfoCard from '../../../../../../../components/ProviderInfoCard'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import TransactionCard from '../../../../../../../components/TransactionCard'
import WarningModal from '../../../../../../../components/WarningModal'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { REDIRECT_PAYMENT_STATUS } from '../../../../../../../constants/payment'
import {
  formatMoney,
  getNameOrKeyForDropdown,
  getTransportValue,
} from '../../../../../../../helpers/utility'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../../lang'
import { downloadFile } from '../../../../../../../methods/file'
import { useGetDownloadPdf } from '../../../state/hooks/useMarineCargo'
import PolicyInfo from '../../../../../../../components/PolicyCancelledRejectionInfo'
import { MarineCargoLandingStyle } from './index.style'

function MarineCargoLanding(props) {
  const { policy, match } = props
  const [showModal, setShowModal] = useState(false)
  const policyId = get(match, 'params.policyId')
  const [{ GET_DOWNLOAD_PDF_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ GET_DOWNLOAD_PDF_ERROR, getDownloadPdfStatus }, dispatchError] =
    useErrorContextValue()

  const [{ getDownloadPdfData }, getDownloadPdfRequest] = useGetDownloadPdf()
  const isApplicationCancelled = ['CANCELLED', 'REJECTED'].includes(
    policy?.policy_status
  )

  useEffect(() => {
    if (GET_DOWNLOAD_PDF_ERROR && getDownloadPdfStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getDownloadPdfStatus,
      })
      dispatchError(
        resetError({
          getDownloadPdfStatus: '',
        })
      )
    }
    if (getDownloadPdfStatus === 'success' && getDownloadPdfData) {
      downloadFile(getDownloadPdfData.pdf_url)
      dispatchError(
        resetError({
          getDownloadPdfStatus: '',
        })
      )
    }
  }, [
    GET_DOWNLOAD_PDF_ERROR,
    getDownloadPdfStatus,
    dispatchError,
    getDownloadPdfData,
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_DOWNLOAD_PDF_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  const renderRow = useCallback((key1, val1, key2, val2) => {
    return (
      <Row>
        <div className="w-50 mb-10">
          <CustomText
            size="10px"
            color={AgentColorPallette.fontDarkerGrey}
            weight={700}
          >
            {key1}
          </CustomText>
          <CustomText
            size="13px"
            color={AgentColorPallette.regular}
            bottom="10px"
          >
            {val1}
          </CustomText>
        </div>
        <div className="w-50">
          <CustomText
            size="10px"
            color={AgentColorPallette.fontDarkerGrey}
            weight={700}
          >
            {key2}
          </CustomText>
          <CustomText
            size="13px"
            color={AgentColorPallette.regular}
            bottom="10px"
          >
            {val2}
          </CustomText>
        </div>
      </Row>
    )
  }, [])

  const handleBtnClick = (btnType) => {
    // here on basis of click move the user to that page
    if (btnType === 'buyInsuranceBtn') {
      handleBuyInsuranceNow()
      return
    }
    getDownloadPdfRequest({ policyId })
  }

  const handleToggleModal = () => {
    setShowModal(!showModal)
  }

  const handleBuyInsuranceNow = () => {
    // Goto customer Form
    const { policy = {} } = props
    if (policy.payment_by === 'AGENT' && policy.payment_status === 'ACTIVE') {
      handleToggleModal()
      return
    }
    if (
      [
        'APPLICATION_COMPLETED',
        'PAYMENT_PENDING',
        'PROVISIONAL_CREATED',
      ].includes(policy.status)
    ) {
      props.history.push({
        pathname: `/customer/payment/${policy?.product_key}/${policyId}`,
        state: {
          customerSummaryData: policy,
        },
      })
    } else if (policy.status === 'INITIATED') {
      props.history.push({
        pathname: `/customer/marine_cargo/packages/${policyId}/preview`,
        state: {
          policy,
        },
      })
    } else if (
      REDIRECT_PAYMENT_STATUS.includes(get(policy, 'payment_status', ''))
    ) {
      const transactionId = get(policy, 'transaction_ids.customer', '')
      props.history.push(
        `/customer/payment/success/${transactionId}/${policyId}`
      )
    } else if (
      ['APPLICATION_CANCELLED', 'PROVISIONAL_FAILED'].includes(policy.status)
    ) {
      // if this is the state then show the error on landing page
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.sorryApplicationWasCancelled,
      })
    } else {
      props.history.push({
        pathname: `/customer/marine_cargo/policy/${policyId}/form`,
        state: {
          policy,
        },
      })
    }
  }

  const renderPolicyDetail = () => {
    const transportType = get(policy, 'policy_detail.transportation_type', '')

    return (
      <div className="provider-info-card mt-10">
        <CustomText
          size="15px"
          color={AgentColorPallette.black}
          bottom="10px"
          weight={800}
        >
          {LANG_STRINGS.policyDetails}
        </CustomText>
        {renderRow(
          LANG_STRINGS.period,
          LANG_STRINGS.marineCargoPeriod,
          LANG_STRINGS.modeOfTransport,
          getTransportValue(
            get(policy, 'policy_detail.transportation_type', '-')
          )
        )}
        {transportType === 'land' && (
          <>
            {renderRow(
              LANG_STRINGS.vehicleType,
              getNameOrKeyForDropdown(policy, 'policy_detail.vehicle_type'),
              LANG_STRINGS.policeNumber,
              `${get(policy, 'policy_detail.region_code', '-')} ${get(policy, 'policy_detail.vehicle_plate_no', '-')}`
            )}
            {renderRow(
              LANG_STRINGS.totalSumInsured,
              formatMoney(get(policy, 'total_sum_insured', '')),
              '',
              ''
            )}
          </>
        )}
        {transportType === 'sea' && (
          <>
            {renderRow(
              LANG_STRINGS.shipType,
              getNameOrKeyForDropdown(policy, 'policy_detail.ship_type'),
              LANG_STRINGS.shipMaterials,
              getNameOrKeyForDropdown(policy, 'policy_detail.ship_material')
            )}
            {renderRow(
              LANG_STRINGS.shipClassification,
              getNameOrKeyForDropdown(policy, 'policy_detail.ship_class'),
              LANG_STRINGS.shipManufacturingYear,
              get(policy, 'policy_detail.year', '-')
            )}
            {renderRow(
              LANG_STRINGS.totalSumInsured,
              formatMoney(get(policy, 'total_sum_insured', '')),
              '',
              ''
            )}
          </>
        )}
        {transportType === 'air' && (
          <>
            {renderRow(
              LANG_STRINGS.airPlaneRegistrationNo,
              get(policy, 'policy_detail.plane_registration_no', '-'),
              LANG_STRINGS.airplaneRegistrationName,
              get(policy, 'policy_detail.airplane_name', '-')
            )}
            {renderRow(
              LANG_STRINGS.flightNo,
              get(policy, 'policy_detail.flight_no', ''),
              LANG_STRINGS.totalSumInsured,
              formatMoney(get(policy, 'total_sum_insured', '-'))
            )}
          </>
        )}
      </div>
    )
  }

  return (
    <CircularLoader isLoading={GET_DOWNLOAD_PDF_LOADER}>
      <MarineCargoLandingStyle>
        <PolicyInfo
          remarks={policy?.insurance_details?.remark_details || {}}
          status={policy?.policy_status || ''}
        />
        <div className="content">
          <ProviderInfoCard
            logo={get(policy, 'product.provider.logo_url', '')}
            providerName={get(policy, 'product.provider.name', '')}
            productName={get(policy, 'product.name', '')}
            applicationNo={get(policy, 'application_no', '')}
            branch={policy?.policy_detail?.provider_branch}
          />
          <InsuranceInfoCard
            isShowDisclaimer
            className="insurance-info"
            tnc={get(policy, 'product.tnc.data', [])}
            benefit={get(policy, 'product.benefit.data[0].description', '')}
            claims={get(policy, 'product.claims.[0].description', '')}
          />
          <div className="provider-info-card mt-10">
            <CustomText
              size="15px"
              color={AgentColorPallette.black}
              bottom="10px"
              weight={800}
            >
              {LANG_STRINGS.agentDetails}
            </CustomText>
            {renderRow(
              LANG_STRINGS.name,
              get(policy, 'agent_info.name'),
              'ID',
              get(policy, 'agent_info.agent_code')
            )}
            {renderRow(
              LANG_STRINGS.enterNumberAsInKtp,
              get(policy, 'agent_info.ktp', '-'),
              LANG_STRINGS.customerPhone,
              get(policy, 'agent_info.phone_no')
            )}
          </div>
          {renderPolicyDetail()}
          <TransactionCard
            disableDiscountEdit
            commission={get(policy, 'product.commission')}
            maxDiscount={get(policy, 'product.max_discount')}
            subTotal={get(policy, 'product.sub_total')}
            discountPercent={get(policy, 'product.discount_percentage')}
            basicPremium={get(policy, 'product.basic_premium')}
            totalTax={get(policy, 'total_tax')}
            stampDuty={get(policy, 'stamp_duty')}
            adminFee={get(policy, 'admin_fee')}
            serviceFee={get(policy, 'service_fee')}
            discount={get(policy, 'discount')}
            totalBill={get(policy, 'subtotal_bill') + get(policy, 'discount')}
            handleEditDiscount={() => {}}
          />
        </div>
        {!isApplicationCancelled && (
          <Row className="cargo-btn-box" justify="space-between">
            <Button
              onClick={handleBtnClick}
              backgroundColor={AgentColorPallette.cyanBlue}
              color={AgentColorPallette.white}
              id="cargo-sq-pdf-download-click"
              className="customer-landing-btn"
            >
              {LANG_STRINGS.download}
            </Button>
            <div className="space" />
            <Button
              onClick={() => {
                handleBtnClick('buyInsuranceBtn')
              }}
              id="cargo-sq-buy-click"
              className="customer-landing-btn"
            >
              {LANG_STRINGS.buy}
            </Button>
          </Row>
        )}
        <WarningModal
          showModal={showModal}
          hideCloseBtn
          hideIcon
          warning={LANG_STRINGS.youCanNotPayThisCustomer}
          onClose={handleToggleModal}
          onOk={handleToggleModal}
        />
        <ShowSnackbar hideOkay />
      </MarineCargoLandingStyle>
    </CircularLoader>
  )
}

export default withRouter(MarineCargoLanding)
