import { get, size } from 'lodash'
import { CustomText } from '../../../../../../../../components'
import AmountTitle from '../../../../../../../../components/AmountTitle'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../../lang'
import { getPropertyPremium } from '../../../../constants'
import { PropertyPremiumStyle } from './index.style'
import PropertyTransactionDetail from '../PropertyTransactionDetail'

function PropertyPremiumSummary (props) {
  const { policy = {}, isManualOrder } = props
  const addons = get(policy, 'product.add_ons', [])

  policy.premium_breakup = {
    ...policy.premium_breakup,
    discount: policy.discount,
    admin_fee: policy.admin_fee,
    stamp_duty: policy.stamp_duty
  }

  const getSectionTitleContainer = (title) => (
    <CustomText
      color={AgentColorPallette.mustard}
      size='14px'
      bottom='10px'
      weight={800}
    >
      {title}
    </CustomText>
  )

  return (
    <PropertyPremiumStyle>
      <div className='section-cost'>
        {
          getSectionTitleContainer('Nilai Properti')
        }
        {
          getPropertyPremium(policy, isManualOrder).map(item => (
            <AmountTitle
              key={item.title}
              title={item.title}
              amount={item.value}
              amountWeight={400}
              className='property-amount'
              size='10px'
            />
          ))
        }
        <div className='separator' />
        <AmountTitle
          title={LANG_STRINGS.totalSumInsured}
          titleWeight={800}
          amount={get(policy, 'total_sum_insured', 0)}
          className='property-amount'
          size='10px'
        />
      </div>
      <div className='section-cost'>
        <CustomText
          color={AgentColorPallette.mustard}
          size='14px'
          lineHeight='14px'
          weight={800}
          bottom='8px'
        >
          Detail Transaksi
        </CustomText>
        <CustomText
          color={AgentColorPallette.earthGreen}
          size='10px'
          lineHeight='14px'
          weight={600}
          bottom='16px'
        >
          *Total Nilai Pertanggungan
        </CustomText>
        <CustomText
          color={AgentColorPallette.mustard}
          size='10px'
          lineHeight='14px'
          weight={800}
          bottom='8px'
        >
          Perhitungan Premi
        </CustomText>
        <PropertyTransactionDetail data={policy.premium_breakup} />
      </div>
      {
        !!size(addons) && (
          <div className='section-cost'>
            {
              getSectionTitleContainer(`4.2 ${LANG_STRINGS.additionalProtection}`)
            }
            {
              addons.map((addon, index) => (
                <AmountTitle
                  key={`customer_addon_${index}`}
                  title={`${index + 1} ${addon.add_on_name}`}
                  amount={addon.premium}
                  amountWeight={400}
                  className='property-amount'
                />
              ))
            }
            <div className='separator' />
            <AmountTitle
              title={LANG_STRINGS.totalAccidentProtection}
              titleWeight={800}
              amount={get(policy, 'product.add_on_premium', 0)}
              className='property-amount'
            />
          </div>
        )
      }
    </PropertyPremiumStyle>
  )
}

export default PropertyPremiumSummary
