import { ConfigUrl } from '../../../../../configs/url'

export const MARINE_CARGO_ACTIONS = {
  GET_CUSTOMER_APPLICATION_DETAIL_REQUEST: 'GET_CUSTOMER_APPLICATION_DETAIL_REQUEST',
  GET_CUSTOMER_APPLICATION_DETAIL: 'GET_CUSTOMER_APPLICATION_DETAIL',

  GET_DOWNLOAD_PDF_REQUEST: 'GET_DOWNLOAD_PDF_REQUEST',
  GET_DOWNLOAD_PDF: 'GET_DOWNLOAD_PDF',

  SUBMIT_CUSTOMER_POLICY_REQUEST: 'SUBMIT_CUSTOMER_POLICY_REQUEST',
  SUBMIT_CUSTOMER_POLICY: 'SUBMIT_CUSTOMER_POLICY'
}

export const getCustomerApplicationDetail = (payload) => ({
  type: MARINE_CARGO_ACTIONS.GET_CUSTOMER_APPLICATION_DETAIL_REQUEST,
  payload: {
    ...payload,
    query: { show_agent: 1, include_insurance_details: true },
    method: 'get',
    url: ConfigUrl.getCustomerPolicyData(payload.policyId)
  }
})

export const getDownloadPdf = (payload) => ({
  type: MARINE_CARGO_ACTIONS.GET_DOWNLOAD_PDF_REQUEST,
  payload: {
    ...payload,
    method: 'get',
    url: ConfigUrl.downloadPdfApi(payload.policyId)
  }
})

export const submitCustomerPolicy = (payload) => ({
  type: MARINE_CARGO_ACTIONS.SUBMIT_CUSTOMER_POLICY_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.submitCustomerPolicyData(payload.policyId)
  }
})
