import {
  resetError,
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import { useEffect, useMemo } from 'react'
import { Container } from '../../../../../components'
import ShowSnackbar from '../../../../../components/ShowNotification'
import {
  HEALTH_FULL_PROTECTION,
  MARINE_CARGO,
  PROPERTY_PROTECTION,
} from '../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../lang'
import { CustomerContextProvider } from '../../context'
import CustomerPolicy from '../../CustomerPolicy'
import MarineCargoLandingContainer from '../../MarineCargoCustomer/pages/MarineCargoLanding'
// import HealthProtectionLandingContainer from '../../pages/HealthProtection/pages/CustomerLanding'
import PropertyLanding from '../../Property/Pages/PropertyLanding'
import {
  useGetCustomerApplicationDetail,
  useGetCustomerDraftDetails,
} from '../../state/hooks/useCustomerState'
import { useParams } from 'react-router'

function PolicyLandingContainer({ history }) {
  const { policyId, draftQuoteId } = useParams()

  const [{ GET_CUSTOMER_APPLICATION_DETAIL_LOADER }, dispatchLoader] =
    useLoaderContextValue()
  const [
    { getCustomerApplicationDetailData = {}, pdfDownloadLoading },
    getCustomerPolicyDetailRequest,
  ] = useGetCustomerApplicationDetail()
  const [{ getCustomerDraftQuoteDetailData }, getCustomerDraftDetailsReq] =
    useGetCustomerDraftDetails()
  const [{ getCustomerApplicationDetailStatus }, dispatchError] =
    useErrorContextValue()

  const quote = useMemo(() => {
    if (policyId) {
      if (getCustomerApplicationDetailData?.migrated_draft_id) {
        history.replace(
          `/customer/draft/policy/${getCustomerApplicationDetailData.migrated_draft_id}`
        )
        return
      }
      return {
        ...getCustomerApplicationDetailData,
      }
    }

    if (draftQuoteId && getCustomerDraftQuoteDetailData?.policy_details) {
      if (getCustomerDraftQuoteDetailData.policy_application_id) {
        history.replace(
          `/customer/policy/${getCustomerDraftQuoteDetailData.policy_application_id}`
        )
        return
      }
      const policyDetails = getCustomerDraftQuoteDetailData?.policy_details
      const totalBill =
        policyDetails?.total_bill || policyDetails?.package_data?.total_bill

      return {
        agent_info: getCustomerDraftQuoteDetailData.agent_info,
        ...policyDetails?.package_data,
        policy_detail: {
          ...policyDetails,
        },
        product: {
          ...policyDetails.package_data,
          common_clause_content:
            policyDetails?.package_data?.common_clause_content,
          common_deductible_content:
            policyDetails?.package_data?.common_deductible_content,
        },
        premium: {
          period: 12,
          amount: policyDetails?.package_data?.basic_premium,
        },
        discount: policyDetails.discount,
        customer_data: policyDetails.customer_data,
        total_premium: totalBill,
        draft_id: draftQuoteId,
        total_bill: totalBill,
        product_code: policyDetails.product_code,
      }
    }
  }, [
    policyId,
    getCustomerDraftQuoteDetailData,
    draftQuoteId,
    getCustomerApplicationDetailData,
    history,
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_CUSTOMER_APPLICATION_DETAIL_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (policyId) {
      getCustomerPolicyDetailRequest({ policyId })
    }

    if (draftQuoteId) {
      getCustomerDraftDetailsReq({
        draftQuoteId,
      })
    }
  }, [
    policyId,
    getCustomerPolicyDetailRequest,
    draftQuoteId,
    getCustomerDraftDetailsReq,
  ])

  useEffect(() => {
    if (getCustomerApplicationDetailStatus === 'success') {
      dispatchError(
        resetError({
          getCustomerApplicationDetailStatus: '',
        })
      )
    } else if (getCustomerApplicationDetailStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getCustomerApplicationDetailStatus,
      })
      dispatchError(
        resetError({
          getCustomerApplicationDetailStatus: '',
        })
      )
    }
    if (getCustomerApplicationDetailData.status !== 'QUOTATION') {
      const productCode =
        getCustomerApplicationDetailData?.product?.package?.product?.code
      if (productCode === MARINE_CARGO) {
        history.push({
          pathname: `/customer/marine_cargo/packages/${policyId}/preview`,
        })
      } else if (productCode === HEALTH_FULL_PROTECTION) {
        history.push({
          pathname: `/customer/health_protection/${policyId}/preview`,
        })
      }
    }
  }, [
    getCustomerApplicationDetailData,
    history,
    policyId,
    getCustomerApplicationDetailStatus,
    dispatchError,
  ])

  const renderThePage = () => {
    if (policyId && !draftQuoteId) {
      const productCode =
        getCustomerApplicationDetailData?.product?.package?.product?.code
      switch (productCode) {
        case PROPERTY_PROTECTION:
          return (
            <PropertyLanding
              customerPolicy={getCustomerApplicationDetailData}
            />
          )
        case MARINE_CARGO:
          return (
            <MarineCargoLandingContainer
              policy={getCustomerApplicationDetailData}
            />
          )
        // case HEALTH_FULL_PROTECTION:
        //   return <HealthProtectionLandingContainer policy={getCustomerApplicationDetailData} />
        default:
          return <CustomerPolicy customerPolicy={quote} />
      }
    }
    if (draftQuoteId && !policyId) {
      const productCode = quote.product_code
      switch (productCode) {
        case PROPERTY_PROTECTION:
          return <PropertyLanding customerPolicy={quote} />
        default:
          return <CustomerPolicy customerPolicy={quote} />
      }
    }
  }

  return (
    <CustomerContextProvider>
      <Container
        mitraHeader
        hideBottomTabs
        loader={GET_CUSTOMER_APPLICATION_DETAIL_LOADER || pdfDownloadLoading}
        title={LANG_STRINGS.attachmentOffer}
      >
        {(quote?.id || quote?.draft_id) && renderThePage()}
      </Container>
    </CustomerContextProvider>
  )
}

export default PolicyLandingContainer
